    adcs_quat_t q_est_n, q_tgt_n, q_conj, q_err;
    adcs_vec3_t vec;
    double s, w, angle;
    adcs_status_t st;

    if ((estimated == NULL) || (target == NULL) || (error == NULL))
        return ADCS_E_NULL;

    error->x = 0.0;
    error->y = 0.0;
    error->z = 0.0;

    if ((!isfinite(estimated->w)) || (!isfinite(estimated->x)) ||
        (!isfinite(estimated->y)) || (!isfinite(estimated->z)) ||
        (!isfinite(target->w)) || (!isfinite(target->x)) ||
        (!isfinite(target->y)) || (!isfinite(target->z)))
        return ADCS_E_DEGENERATE;

    st = adcs_quat_normalize(estimated, &q_est_n);
    if (st != ADCS_OK)
        return ADCS_E_DEGENERATE;
    st = adcs_quat_normalize(target, &q_tgt_n);
    if (st != ADCS_OK)
        return ADCS_E_DEGENERATE;

    q_conj = adcs_quat_conjugate(&q_est_n);
    q_err = adcs_quat_multiply(&q_tgt_n, &q_conj);

    if (q_err.w < 0.0) {
        q_err.w = -q_err.w;
        q_err.x = -q_err.x;
        q_err.y = -q_err.y;
        q_err.z = -q_err.z;
    }

    vec.x = q_err.x;
    vec.y = q_err.y;
    vec.z = q_err.z;
    w = q_err.w;
    s = sqrt(vec.x * vec.x + vec.y * vec.y + vec.z * vec.z);

    if (s <= 1.0e-12) {
        error->x = 2.0 * vec.x;
        error->y = 2.0 * vec.y;
        error->z = 2.0 * vec.z;
    } else {
        angle = 2.0 * atan2(s, w);
        error->x = angle * vec.x / s;
        error->y = angle * vec.y / s;
        error->z = angle * vec.z / s;
    }

    return ADCS_OK;
}

